import { randomUUID } from "node:crypto";
import { stat } from "node:fs/promises";
import { basename, join } from "node:path";
import type {
  ChatAttachment,
  ChatMessage,
  NodeProfile,
  ShareOffer,
  TransferStatus,
} from "@envoymesh/api";
import {
  chatRoomThreadKey,
  deferredDirectChatAttachmentKey,
} from "@envoymesh/api";
import {
  createShareAcceptPayload,
  createShareRequestPayload,
  createUnsignedEnvelope,
  parseShareAcceptPayload,
  type EnvoyEnvelope,
} from "@envoymesh/protocol";
import { derivePeerId, signUnsignedEnvelope } from "@envoymesh/identity";
import type { EnvoyMesh } from "@envoymesh/network";
import type {
  LocalPeerDirectoryStore,
  LocalTaskStore,
  LocalTrustStore,
} from "@envoymesh/local-store";
import type { ChatDeliverResult } from "./chat-outbound-deliver.js";
import { sendVaultFileViaDataTransfer } from "./node-file-share.js";
import { TransferTracker } from "./transfer-tracker.js";
import { isSafeVaultPath } from "./share-inbound.js";
import { mergeDialablePeerListenAddrs } from "./outbound-dial-hints.js";

// ---------------------------------------------------------------------------
// Helpers (moved from node-service-impl.ts)
// ---------------------------------------------------------------------------

function raceWithTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {
  return new Promise((resolve, reject) => {
    let settled = false;
    const t = setTimeout(() => {
      if (settled) return;
      settled = true;
      reject(new Error(`Operation timed out after ${ms}ms: ${label}`));
    }, ms);
    promise
      .then((val) => {
        if (settled) return;
        settled = true;
        clearTimeout(t);
        resolve(val);
      })
      .catch((err) => {
        if (settled) return;
        settled = true;
        clearTimeout(t);
        reject(err);
      });
  });
}

function mimeTypeForFilename(filename: string): string {
  const ext = filename.includes(".") ? filename.slice(filename.lastIndexOf(".") + 1).toLowerCase() : "";
  switch (ext) {
    case "pdf":  return "application/pdf";
    case "png":  return "image/png";
    case "jpg": case "jpeg": return "image/jpeg";
    case "gif":  return "image/gif";
    case "webp": return "image/webp";
    case "svg":  return "image/svg+xml";
    case "webm": return "audio/webm";
    case "m4a":  return "audio/mp4";
    case "mp4":  return "video/mp4";
    case "mp3":  return "audio/mpeg";
    case "ogg": case "oga": return "audio/ogg";
    case "wav":  return "audio/wav";
    case "txt":  return "text/plain";
    case "md":   return "text/markdown";
    case "json": return "application/json";
    case "html": return "text/html";
    case "csv":  return "text/csv";
    default:     return "application/octet-stream";
  }
}

function sanitizeChatFilename(name: string): string {
  const base = basename(name.trim()) || "file";
  return base.replace(/[^a-zA-Z0-9._-]+/g, "_").slice(0, 200);
}

function chatInboundVaultPath(senderOwnerId: string, senderRelativePath: string): string {
  const safeOwner =
    senderOwnerId.replace(/[^a-zA-Z0-9_-]+/g, "_").replace(/^_+|_+$/g, "") || "peer";
  const filename = sanitizeChatFilename(basename(senderRelativePath));
  return `chat/in/${safeOwner}/${filename}`;
}

// ---------------------------------------------------------------------------
// Deps interface
// ---------------------------------------------------------------------------

export interface NodeFileShareDeps {
  // Profile / Mesh / Online
  assertOnline(): void;
  recordOwnerActivity(): void;
  requireProfile(): NodeProfile;
  requireMesh(): EnvoyMesh;
  reachableMesh(): EnvoyMesh | undefined;

  // Transport & delivery
  resolvePeerTransportForOwner(targetOwnerId: string): Promise<{
    transportPeerId: string;
    recipientEnvelopePeerId: string | undefined;
    listenAddrs: string[] | undefined;
  }>;
  deliverCallEnvelope(
    transportPeerId: string,
    envelope: EnvoyEnvelope,
    dialHints: string[],
    listenAddrs?: string[],
  ): Promise<ChatDeliverResult>;
  dialHintsForChat(
    recipientPeerId: string,
    peerListenAddrs: string[] | undefined,
  ): Promise<string[]>;
  mergeConnectionDialHints(
    peerId: string,
    peerListenAddrs: string[] | undefined,
    inboundConnectionAddrs: string[] | undefined,
  ): string[] | undefined;
  tagBondedContactReachability(libp2pPeerId: string): void;

  // Chat helpers (implemented on NodeServiceImpl)
  recordFileShareInChat(input: {
    peerOwnerId: string;
    outgoing: boolean;
    vaultRelativePath: string;
    byteLength: number;
    sensitivity?: ChatAttachment["sensitivity"];
    mimeType?: string;
    textOverride?: string;
  }): Promise<void>;
  applyRoomAttachmentVaultPath(input: {
    roomId: string;
    messageId: string;
    attachmentId: string;
    vaultRelativePath: string;
  }): Promise<void>;
  applyDirectChatAttachmentVaultPath(input: {
    peerOwnerId: string;
    messageId: string;
    attachmentId: string;
    vaultRelativePath: string;
  }): Promise<void>;
  persistChatMessage(threadPeerOwnerId: string, msg: ChatMessage): void;

  // Event emission
  emit(event: string | symbol, data: unknown): void;

  // Stores needed directly
  taskStore: LocalTaskStore | undefined;
  vaultDir: string;
  peerDirectoryStore: LocalPeerDirectoryStore;
  trustStore: LocalTrustStore;
}

// ---------------------------------------------------------------------------
// Runtime
// ---------------------------------------------------------------------------

export class NodeFileShareRuntime {
  // Transfer tracking
  readonly transferTracker = new TransferTracker();

  // Outbound push: our `share.request` message id → until we receive `share.preview`.
  readonly pendingPushShareByRequestMsgId = new Map<
    string,
    { relativePath: string; toPeerId: string; deliveryChannel?: "inbox" | "chat" | "agent" }
  >();

  // Outbound pull: peer vault path requested via fileOrigin=responder until preview arrives.
  readonly pendingPullShareByRequestMsgId = new Map<
    string,
    {
      peerRelativePath: string;
      targetOwnerId: string;
      toPeerId: string;
      sensitivity: "public" | "friends" | "private";
    }
  >();

  // After inbound `share.preview`: preview message id → send file to peer (we are holder).
  readonly pendingFileSendByPreviewMsgId = new Map<
    string,
    { relativePath: string; toPeerId: string; deliveryChannel?: "inbox" | "chat" | "agent" }
  >();

  // `share.accept` arrived before inbound `share.preview` linked the pending send.
  readonly deferredShareAcceptByPreviewId = new Map<
    string,
    {
      envelope: EnvoyEnvelope;
      remotePeerId: string;
      taskStore: LocalTaskStore;
      vaultDir: string;
      inboundConnectionAddrs?: string[];
    }
  >();

  // Inbound push offers waiting for accept/decline — keyed by preview message id.
  readonly pendingInboundShareOffers = new Map<string, ShareOffer>();

  // Pending vault-relative rename on receive.
  readonly pendingDataTransferSavePath = new Map<string, string>();

  // Share / data-transfer correlation ids for progress tracking.
  readonly correlationByRequestMsgId = new Map<string, string>();
  readonly correlationByPreviewMsgId = new Map<string, string>();

  // Inbound accept waiting for bytes — keyed by preview/share id.
  readonly inboundTransferByShareId = new Map<
    string,
    {
      senderNodeId: string;
      senderVaultRelativePath: string;
      savePath: string;
      senderOwnerId?: string;
      chatRoomId?: string;
      chatMessageId?: string;
      chatAttachmentId?: string;
    }
  >();

  // Vault paths for 1:1 chat attachments when transfer completes before chat.message is persisted.
  readonly deferredDirectChatAttachmentVaultPath = new Map<string, string>();

  constructor(private readonly deps: NodeFileShareDeps) {}

  // -----------------------------------------------------------------------
  // Transfer status helpers
  // -----------------------------------------------------------------------

  upsertTransferStatus(status: TransferStatus): TransferStatus {
    const saved = this.transferTracker.upsert(status);
    this.deps.emit("share:progress", saved);
    return saved;
  }

  async listActiveTransfers(): Promise<TransferStatus[]> {
    return this.transferTracker.listActive();
  }

  async getTransferStatus(correlationId: string): Promise<TransferStatus | undefined> {
    return this.transferTracker.get(correlationId);
  }

  // -----------------------------------------------------------------------
  // notifyInboundTransferVerified
  // -----------------------------------------------------------------------

  notifyInboundTransferVerified(input: {
    remotePeerId: string;
    relativePath: string;
    totalBytes: number;
  }): void {
    for (const [shareId, pending] of this.inboundTransferByShareId.entries()) {
      if (pending.senderNodeId !== input.remotePeerId) continue;
      if (pending.savePath !== input.relativePath && pending.senderVaultRelativePath !== input.relativePath) {
        continue;
      }
      const correlationId = this.correlationByPreviewMsgId.get(shareId) ?? shareId;
      this.upsertTransferStatus({
        correlationId,
        phase: "verified",
        bytesTransferred: input.totalBytes,
        totalBytes: input.totalBytes,
        remotePeerId: input.remotePeerId,
        remotePeerOwnerId: pending.senderOwnerId,
        vaultRelativePath: input.relativePath,
        updatedAt: new Date().toISOString(),
      });
      this.inboundTransferByShareId.delete(shareId);
      if (pending.chatRoomId && pending.chatMessageId && pending.chatAttachmentId) {
        void this.deps.applyRoomAttachmentVaultPath({
          roomId: pending.chatRoomId,
          messageId: pending.chatMessageId,
          attachmentId: pending.chatAttachmentId,
          vaultRelativePath: input.relativePath,
        });
      } else if (pending.chatMessageId && pending.chatAttachmentId && pending.senderOwnerId) {
        void this.deps.applyDirectChatAttachmentVaultPath({
          peerOwnerId: pending.senderOwnerId,
          messageId: pending.chatMessageId,
          attachmentId: pending.chatAttachmentId,
          vaultRelativePath: input.relativePath,
        });
      } else {
        void this.deps.recordFileShareInChat({
          peerOwnerId: pending.senderOwnerId ?? pending.senderNodeId,
          outgoing: false,
          vaultRelativePath: input.relativePath,
          byteLength: input.totalBytes,
        });
      }
      return;
    }

    // Transfer not linked to a share — still record progress for UI.
    const correlationId = `inbound:${input.remotePeerId}:${input.relativePath}`;
    this.upsertTransferStatus({
      correlationId,
      phase: "verified",
      bytesTransferred: input.totalBytes,
      totalBytes: input.totalBytes,
      remotePeerId: input.remotePeerId,
      vaultRelativePath: input.relativePath,
      updatedAt: new Date().toISOString(),
    });
  }

  // -----------------------------------------------------------------------
  // linkOutboundSharePreviewFromInbound
  // -----------------------------------------------------------------------

  linkOutboundSharePreviewFromInbound(
    previewMessageId: string,
    inReplyToRequestMsgId: string,
  ): void {
    const pending = this.pendingPushShareByRequestMsgId.get(inReplyToRequestMsgId);
    if (!pending) {
      console.warn(
        `[share] preview ${previewMessageId.slice(0, 12)}…: no pending push send for request ${inReplyToRequestMsgId.slice(0, 12)}…`,
      );
      return;
    }
    this.pendingFileSendByPreviewMsgId.set(previewMessageId, {
      relativePath: pending.relativePath,
      toPeerId: pending.toPeerId,
      deliveryChannel: pending.deliveryChannel,
    });
    this.pendingPushShareByRequestMsgId.delete(inReplyToRequestMsgId);
    console.log(
      `[share] linked preview ${previewMessageId.slice(0, 12)}… → file send ${pending.relativePath} to ${pending.toPeerId.slice(0, 12)}…`,
    );
    const correlationId = this.correlationByRequestMsgId.get(inReplyToRequestMsgId);
    if (correlationId) {
      this.correlationByPreviewMsgId.set(previewMessageId, correlationId);
      this.correlationByRequestMsgId.delete(inReplyToRequestMsgId);
    }
    const deferred = this.deferredShareAcceptByPreviewId.get(previewMessageId);
    if (deferred) {
      this.deferredShareAcceptByPreviewId.delete(previewMessageId);
      void this.maybeSendShareFileForInboundAccept(deferred).catch((err) => {
        console.error(
          `[share] deferred file transfer failed for preview ${previewMessageId.slice(0, 12)}…:`,
          err instanceof Error ? err.message : err,
        );
      });
    }
  }

  // -----------------------------------------------------------------------
  // recordInboundPullSharePreview
  // -----------------------------------------------------------------------

  recordInboundPullSharePreview(input: {
    previewMessageId: string;
    inReplyToRequestMsgId: string;
    senderPeerId: string;
    senderOwnerId?: string;
    previewText: string;
    sensitivity: "public" | "friends" | "private";
  }): boolean {
    const pending = this.pendingPullShareByRequestMsgId.get(input.inReplyToRequestMsgId);
    if (!pending) return false;
    this.pendingPullShareByRequestMsgId.delete(input.inReplyToRequestMsgId);
    void this.recordInboundPushShareOffer({
      shareId: input.previewMessageId,
      senderPeerId: input.senderPeerId,
      senderOwnerId: input.senderOwnerId ?? pending.targetOwnerId,
      previewText: input.previewText,
      sensitivity: input.sensitivity,
      relativePath: pending.peerRelativePath,
      deliveryChannel: "inbox",
    });
    const correlationId = this.correlationByRequestMsgId.get(input.inReplyToRequestMsgId);
    if (correlationId) {
      this.correlationByPreviewMsgId.set(input.previewMessageId, correlationId);
      this.correlationByRequestMsgId.delete(input.inReplyToRequestMsgId);
    }
    return true;
  }

  // -----------------------------------------------------------------------
  // registerResponderFileSendAfterPreview
  // -----------------------------------------------------------------------

  registerResponderFileSendAfterPreview(
    previewMessageId: string,
    relativePath: string | undefined,
    requesterPeerId: string,
  ): void {
    const rel = relativePath?.replace(/^[\\/]+/, "") ?? "";
    if (!rel.trim()) return;
    this.pendingFileSendByPreviewMsgId.set(previewMessageId, {
      relativePath: rel,
      toPeerId: requesterPeerId,
    });
  }

  // -----------------------------------------------------------------------
  // recordInboundPushShareOffer
  // -----------------------------------------------------------------------

  async recordInboundPushShareOffer(input: {
    shareId: string;
    senderPeerId: string;
    senderOwnerId?: string;
    previewText: string;
    sensitivity: "public" | "friends" | "private";
    relativePath: string;
    deliveryChannel?: "inbox" | "chat" | "agent";
    chatRoomId?: string;
    chatMessageId?: string;
    chatAttachmentId?: string;
  }): Promise<void> {
    const records = await this.deps.peerDirectoryStore.listPeerRecords();
    const rec = records.find((r) => r.peerId === input.senderPeerId);
    const senderOwnerId = input.senderOwnerId ?? rec?.ownerId;
    const trust = senderOwnerId
      ? await this.deps.trustStore.getTrustRecord(senderOwnerId)
      : undefined;
    const displayName =
      trust?.displayName?.trim() ||
      (senderOwnerId
        ? senderOwnerId.replace(/^envoy:owner:/, "").slice(0, 10)
        : `${input.senderPeerId.slice(0, 12)}…`);
    const filename = basename(input.relativePath) || "file";
    const offer: ShareOffer = {
      shareId: input.shareId,
      senderNodeId: input.senderPeerId,
      senderOwnerId,
      senderDisplayName: displayName,
      filename,
      mimeType: "application/octet-stream",
      sizeBytes: 0,
      sensitivity: input.sensitivity,
      preview: input.previewText,
      timestamp: new Date().toISOString(),
      senderVaultRelativePath: input.relativePath.replace(/^[\\/]+/, "") || undefined,
      chatRoomId: input.chatRoomId,
      chatMessageId: input.chatMessageId,
      chatAttachmentId: input.chatAttachmentId,
    };
    this.pendingInboundShareOffers.set(input.shareId, offer);
    if (input.deliveryChannel !== "chat") {
      this.deps.emit("share:offered", offer);
    }
  }

  // -----------------------------------------------------------------------
  // clearPendingShareStateForPreview
  // -----------------------------------------------------------------------

  clearPendingShareStateForPreview(previewMessageId: string): void {
    this.pendingFileSendByPreviewMsgId.delete(previewMessageId);
    const offer = this.pendingInboundShareOffers.get(previewMessageId);
    if (offer?.senderVaultRelativePath) {
      this.pendingDataTransferSavePath.delete(
        `${offer.senderNodeId}\n${offer.senderVaultRelativePath.replace(/^[\\/]+/, "")}`,
      );
    }
    this.pendingInboundShareOffers.delete(previewMessageId);
  }

  // -----------------------------------------------------------------------
  // resolveInboundDataTransferRelativePath
  // -----------------------------------------------------------------------

  resolveInboundDataTransferRelativePath(
    remotePeerId: string,
    voucherRelativePath: string,
  ): string {
    const norm = voucherRelativePath.replace(/^[\\/]+/, "");
    const o = this.pendingDataTransferSavePath.get(`${remotePeerId}\n${norm}`);
    return o ?? norm;
  }

  // -----------------------------------------------------------------------
  // consumeInboundDataTransferSaveMapping
  // -----------------------------------------------------------------------

  consumeInboundDataTransferSaveMapping(
    remotePeerId: string,
    voucherSourceRelativePath: string,
  ): void {
    const norm = voucherSourceRelativePath.replace(/^[\\/]+/, "");
    this.pendingDataTransferSavePath.delete(`${remotePeerId}\n${norm}`);
  }

  // -----------------------------------------------------------------------
  // maybeSendShareFileForInboundAccept
  // -----------------------------------------------------------------------

  async maybeSendShareFileForInboundAccept(input: {
    envelope: EnvoyEnvelope;
    remotePeerId: string;
    taskStore: LocalTaskStore;
    vaultDir: string;
    inboundConnectionAddrs?: string[];
  }): Promise<void> {
    let payload: ReturnType<typeof parseShareAcceptPayload>;
    try {
      payload = parseShareAcceptPayload(input.envelope.payload);
    } catch {
      return;
    }
    if (!payload.accept) return;
    const previewId = payload.inReplyTo;
    const pending = this.pendingFileSendByPreviewMsgId.get(previewId);
    if (!pending) {
      console.warn(
        `[share] share.accept for preview ${previewId.slice(0, 12)}…: deferring until preview is linked`,
      );
      this.deferredShareAcceptByPreviewId.set(previewId, input);
      return;
    }
    if (pending.toPeerId !== input.remotePeerId) {
      console.warn(
        `[share] file send skipped: peer mismatch for preview=${previewId.slice(0, 12)}…`,
      );
      return;
    }
    const mesh = this.deps.reachableMesh();
    const profile = this.deps.requireProfile();
    if (!mesh) return;

    const peerRecords = await this.deps.peerDirectoryStore.listPeerRecords();
    const rec = peerRecords.find((r) => r.peerId === input.remotePeerId);
    const listenAddrs = this.deps.mergeConnectionDialHints(
      input.remotePeerId,
      rec?.listenAddrs,
      input.inboundConnectionAddrs,
    );
    let dialHints: string[];
    try {
      dialHints = await raceWithTimeout(
        this.deps.dialHintsForChat(input.remotePeerId, listenAddrs),
        30_000,
        "_dialHintsForChat",
      );
    } catch (err) {
      console.error(
        `[share] dial hints failed for data transfer to ${input.remotePeerId.slice(0, 12)}…:`,
        err instanceof Error ? err.message : err,
      );
      throw err;
    }

    const correlationId =
      this.correlationByPreviewMsgId.get(previewId) ?? input.envelope.correlationId ?? previewId;
    this.upsertTransferStatus({
      correlationId,
      phase: "transferring",
      remotePeerId: input.remotePeerId,
      vaultRelativePath: pending.relativePath,
      updatedAt: new Date().toISOString(),
    });

    console.log(
      `[share] data transfer start: ${pending.relativePath} → ${input.remotePeerId.slice(0, 12)}… (${dialHints.length} dial hints)`,
    );
    await sendVaultFileViaDataTransfer({
      mesh,
      profile,
      taskStore: input.taskStore,
      vaultDir: input.vaultDir,
      relativePath: pending.relativePath,
      toPeerId: input.remotePeerId,
      dialHints,
      peerListenAddrs: listenAddrs,
      rebuildDialHints: () => this.deps.dialHintsForChat(input.remotePeerId, listenAddrs),
      transferHooks: {
        correlationId,
        remotePeerOwnerId: rec?.ownerId,
        onUpdate: (status) => this.upsertTransferStatus(status as TransferStatus),
      },
    });
    this.pendingFileSendByPreviewMsgId.delete(previewId);
    this.deferredShareAcceptByPreviewId.delete(previewId);
    console.log(
      `[share] data transfer complete: ${pending.relativePath} → ${input.remotePeerId.slice(0, 12)}…`,
    );
    if (rec?.ownerId && pending.deliveryChannel !== "chat") {
      let byteLength = 0;
      try {
        const st = await stat(join(input.vaultDir, pending.relativePath));
        byteLength = st.size;
      } catch {
        /* ignore */
      }
      void this.deps.recordFileShareInChat({
        peerOwnerId: rec.ownerId,
        outgoing: true,
        vaultRelativePath: pending.relativePath,
        byteLength,
      });
    }
  }

  // -----------------------------------------------------------------------
  // listPendingShareOffers
  // -----------------------------------------------------------------------

  async listPendingShareOffers(): Promise<ShareOffer[]> {
    return [...this.pendingInboundShareOffers.values()];
  }

  // -----------------------------------------------------------------------
  // shareFile (public)
  // -----------------------------------------------------------------------

  async shareFile(
    targetOwnerId: string,
    file: {
      path: string;
      sensitivity: "public" | "friends" | "private";
      deliveryChannel?: "inbox" | "chat" | "agent";
    },
  ): Promise<void> {
    await this.shareFileInternal(targetOwnerId, file);
  }

  // -----------------------------------------------------------------------
  // requestShareFromLibrary (public)
  // -----------------------------------------------------------------------

  async requestShareFromLibrary(
    targetOwnerId: string,
    file: {
      relativePath: string;
      sensitivity: "public" | "friends" | "private";
      correlationId?: string;
    },
  ): Promise<{ shareRequestMessageId: string }> {
    return this.requestShareFromLibraryInternal(targetOwnerId, file);
  }

  // -----------------------------------------------------------------------
  // _shareFileInternal
  // -----------------------------------------------------------------------

  private async shareFileInternal(
    targetOwnerId: string,
    file: {
      path: string;
      sensitivity: "public" | "friends" | "private";
      deliveryChannel?: "inbox" | "chat" | "agent";
      chatRoomId?: string;
      chatMessageId?: string;
      chatAttachmentId?: string;
    },
  ): Promise<{ shareRequestMessageId: string }> {
    this.deps.assertOnline();
    this.deps.recordOwnerActivity();
    const profile = this.deps.requireProfile();
    if (!this.deps.taskStore) {
      throw new Error("Task store not initialized — node is not fully wired");
    }

    const { transportPeerId, recipientEnvelopePeerId, listenAddrs } =
      await this.deps.resolvePeerTransportForOwner(targetOwnerId);

    const norm = file.path.replace(/^[\\/]+/, "");
    if (!isSafeVaultPath(this.deps.vaultDir, norm)) {
      throw new Error("Invalid vault path");
    }
    await stat(join(this.deps.vaultDir, norm)).catch(() => {
      throw new Error("File not found in vault");
    });

    const mesh = this.deps.requireMesh();
    const conn = mesh.getPeerConnectionInfo(transportPeerId);
    let dialHints: string[];
    if (conn.connected || mesh.getConnectedPeerIds().includes(transportPeerId)) {
      dialHints = [];
    } else {
      dialHints = await raceWithTimeout(
        this.deps.dialHintsForChat(transportPeerId, listenAddrs),
        10_000,
        "_dialHintsForChat",
      );
    }

    const correlationId = randomUUID();
    const unsigned = createUnsignedEnvelope({
      senderPeerId: derivePeerId(profile.device.publicKeyPem),
      senderPublicKey: profile.device.publicKeyPem,
      senderRole: "human",
      recipientPeerId: recipientEnvelopePeerId,
      recipientRole: "human",
      intent: "share.request",
      payload: createShareRequestPayload({
        requestType: "file",
        relativePath: norm,
        requestedSensitivity: file.sensitivity,
        fileOrigin: "sender",
        deliveryChannel: file.deliveryChannel ?? "inbox",
        chatRoomId: file.chatRoomId,
        chatMessageId: file.chatMessageId,
        chatAttachmentId: file.chatAttachmentId,
      }),
      correlationId,
    });
    const envelope = signUnsignedEnvelope(unsigned, profile.device.privateKeyPem) as EnvoyEnvelope;
    await this.deps.deliverCallEnvelope(transportPeerId, envelope, dialHints, listenAddrs);
    this.pendingPushShareByRequestMsgId.set(envelope.messageId, {
      relativePath: norm,
      toPeerId: transportPeerId,
      deliveryChannel: file.deliveryChannel ?? "inbox",
    });
    this.correlationByRequestMsgId.set(envelope.messageId, correlationId);
    this.upsertTransferStatus({
      correlationId,
      phase: "negotiating",
      remotePeerOwnerId: targetOwnerId,
      remotePeerId: transportPeerId,
      vaultRelativePath: norm,
      updatedAt: new Date().toISOString(),
    });
    return { shareRequestMessageId: envelope.messageId };
  }

  // -----------------------------------------------------------------------
  // _requestShareFromLibraryInternal
  // -----------------------------------------------------------------------

  private async requestShareFromLibraryInternal(
    targetOwnerId: string,
    file: {
      relativePath: string;
      sensitivity: "public" | "friends" | "private";
      correlationId?: string;
    },
  ): Promise<{ shareRequestMessageId: string }> {
    this.deps.assertOnline();
    this.deps.recordOwnerActivity();
    const profile = this.deps.requireProfile();
    if (!this.deps.taskStore) {
      throw new Error("Task store not initialized — node is not fully wired");
    }

    const { transportPeerId, recipientEnvelopePeerId, listenAddrs } =
      await this.deps.resolvePeerTransportForOwner(targetOwnerId);
    const peerPath = file.relativePath.replace(/^[\\/]+/, "");

    const mesh = this.deps.requireMesh();
    const conn = mesh.getPeerConnectionInfo(transportPeerId);
    let dialHints: string[];
    if (conn.connected || mesh.getConnectedPeerIds().includes(transportPeerId)) {
      dialHints = [];
    } else {
      dialHints = await raceWithTimeout(
        this.deps.dialHintsForChat(transportPeerId, listenAddrs),
        10_000,
        "_dialHintsForChat",
      );
    }

    const correlationId = file.correlationId ?? randomUUID();
    const unsigned = createUnsignedEnvelope({
      senderPeerId: derivePeerId(profile.device.publicKeyPem),
      senderPublicKey: profile.device.publicKeyPem,
      senderRole: "human",
      recipientPeerId: recipientEnvelopePeerId,
      recipientRole: "human",
      intent: "share.request",
      payload: createShareRequestPayload({
        requestType: "file",
        relativePath: peerPath,
        requestedSensitivity: file.sensitivity,
        fileOrigin: "responder",
        deliveryChannel: "inbox",
        correlationId,
      }),
      correlationId,
    });
    const envelope = signUnsignedEnvelope(unsigned, profile.device.privateKeyPem) as EnvoyEnvelope;
    this.pendingPullShareByRequestMsgId.set(envelope.messageId, {
      peerRelativePath: peerPath,
      targetOwnerId,
      toPeerId: transportPeerId,
      sensitivity: file.sensitivity,
    });
    this.correlationByRequestMsgId.set(envelope.messageId, correlationId);
    await this.deps.deliverCallEnvelope(transportPeerId, envelope, dialHints, listenAddrs);
    this.upsertTransferStatus({
      correlationId,
      phase: "negotiating",
      remotePeerOwnerId: targetOwnerId,
      remotePeerId: transportPeerId,
      vaultRelativePath: peerPath,
      updatedAt: new Date().toISOString(),
    });
    return { shareRequestMessageId: envelope.messageId };
  }

  // -----------------------------------------------------------------------
  // acceptShare
  // -----------------------------------------------------------------------

  async acceptShare(shareId: string, savePath: string): Promise<void> {
    this.deps.assertOnline();
    this.deps.recordOwnerActivity();
    const mesh = this.deps.requireMesh();
    const profile = this.deps.requireProfile();
    const offer = this.pendingInboundShareOffers.get(shareId);
    if (!offer) {
      throw new Error(`No pending share offer for id=${shareId}`);
    }

    const saveNorm = savePath.trim().replace(/^[\\/]+/, "");
    const srcKey = offer.senderVaultRelativePath?.replace(/^[\\/]+/, "") ?? "";
    if (saveNorm) {
      if (!srcKey) {
        throw new Error("Cannot set save path: sender vault path unknown for this offer");
      }
      if (!isSafeVaultPath(this.deps.vaultDir, saveNorm)) {
        throw new Error("Invalid save path");
      }
      this.pendingDataTransferSavePath.set(`${offer.senderNodeId}\n${srcKey}`, saveNorm);
    }

    const records = await this.deps.peerDirectoryStore.listPeerRecords();
    const rec = records.find((r) => r.peerId === offer.senderNodeId);
    const senderOwnerId = offer.senderOwnerId ?? rec?.ownerId;

    let dialHints: string[];
    try {
      dialHints = await raceWithTimeout(
        this.deps.dialHintsForChat(offer.senderNodeId, rec?.listenAddrs),
        30_000,
        "_dialHintsForChat",
      );
    } catch (err) {
      throw err;
    }
    const recipientEnvelopePeerId = rec?.devicePublicKeyPem
      ? derivePeerId(rec.devicePublicKeyPem)
      : undefined;

    const unsigned = createUnsignedEnvelope({
      senderPeerId: derivePeerId(profile.device.publicKeyPem),
      senderPublicKey: profile.device.publicKeyPem,
      senderRole: "human",
      recipientPeerId: recipientEnvelopePeerId,
      recipientRole: "human",
      intent: "share.accept",
      payload: createShareAcceptPayload({ inReplyTo: shareId, accept: true }),
    });
    const envelope = signUnsignedEnvelope(unsigned, profile.device.privateKeyPem) as EnvoyEnvelope;
    await this.deps.deliverCallEnvelope(offer.senderNodeId, envelope, dialHints, rec?.listenAddrs);
    void this.deps.tagBondedContactReachability(offer.senderNodeId);
    this.correlationByPreviewMsgId.set(shareId, shareId);
    this.inboundTransferByShareId.set(shareId, {
      senderNodeId: offer.senderNodeId,
      senderVaultRelativePath: srcKey,
      savePath: saveNorm || srcKey || offer.filename,
      senderOwnerId,
      chatRoomId: offer.chatRoomId,
      chatMessageId: offer.chatMessageId,
      chatAttachmentId: offer.chatAttachmentId,
    });
    this.upsertTransferStatus({
      correlationId: shareId,
      phase: "negotiating",
      remotePeerId: offer.senderNodeId,
      remotePeerOwnerId: senderOwnerId,
      vaultRelativePath: saveNorm || srcKey || offer.filename,
      updatedAt: new Date().toISOString(),
    });
    this.pendingInboundShareOffers.delete(shareId);
    const emitPath = saveNorm || srcKey || offer.filename;
    this.deps.emit("share:accepted", { shareId, savePath: emitPath });
  }

  // -----------------------------------------------------------------------
  // declineShare
  // -----------------------------------------------------------------------

  async declineShare(shareId: string): Promise<void> {
    this.deps.assertOnline();
    this.deps.recordOwnerActivity();
    const mesh = this.deps.requireMesh();
    const profile = this.deps.requireProfile();
    const offer = this.pendingInboundShareOffers.get(shareId);
    if (!offer) {
      throw new Error(`No pending share offer for id=${shareId}`);
    }
    const records = await this.deps.peerDirectoryStore.listPeerRecords();
    const rec = records.find((r) => r.peerId === offer.senderNodeId);
    let dialHints: string[];
    try {
      dialHints = await raceWithTimeout(
        this.deps.dialHintsForChat(offer.senderNodeId, rec?.listenAddrs),
        30_000,
        "_dialHintsForChat",
      );
    } catch (err) {
      throw err;
    }
    const recipientEnvelopePeerId = rec?.devicePublicKeyPem
      ? derivePeerId(rec.devicePublicKeyPem)
      : undefined;
    const unsigned = createUnsignedEnvelope({
      senderPeerId: derivePeerId(profile.device.publicKeyPem),
      senderPublicKey: profile.device.publicKeyPem,
      senderRole: "human",
      recipientPeerId: recipientEnvelopePeerId,
      recipientRole: "human",
      intent: "share.accept",
      payload: createShareAcceptPayload({ inReplyTo: shareId, accept: false }),
    });
    const envelope = signUnsignedEnvelope(unsigned, profile.device.privateKeyPem) as EnvoyEnvelope;
    await this.deps.deliverCallEnvelope(offer.senderNodeId, envelope, dialHints, rec?.listenAddrs);
    this.pendingInboundShareOffers.delete(shareId);
    this.deps.emit("share:declined", { shareId });
  }

  // -----------------------------------------------------------------------
  // maybeAutoAcceptChatShare
  // -----------------------------------------------------------------------

  async maybeAutoAcceptChatShare(input: {
    shareId: string;
    senderOwnerId?: string;
    senderRelativePath: string;
    requiresApproval: boolean;
  }): Promise<void> {
    if (!input.senderOwnerId?.trim()) {
      return;
    }
    const trust = await this.deps.trustStore.getTrustRecord(input.senderOwnerId);
    const level = trust?.level;
    if (!level || level === "blocked" || level === "public") {
      return;
    }
    if (input.requiresApproval) {
      return;
    }
    const savePath = chatInboundVaultPath(input.senderOwnerId, input.senderRelativePath);
    try {
      await this.acceptShare(input.shareId, savePath);
    } catch (err) {
      console.warn(
        `[chat-attachment] auto-accept failed for ${input.shareId.slice(0, 12)}…:`,
        err instanceof Error ? err.message : err,
      );
    }
  }
}

