/**
 * NodeService Call Signaling — Phase 38 Voice/Video Call methods extracted
 * from node-service-impl.ts.
 *
 * Every function takes a `NodeCallSignalingDeps` as its first argument so the
 * host class (NodeServiceImpl) can inject its private state and helpers.
 */

import { randomUUID } from "node:crypto";
import type {
  CallSession,
  CallEvent,
  CallMediaType,
  NodeProfile,
  WarmContactConnectionOptions,
} from "@envoymesh/api";
import {
  createAuditEvent,
} from "@envoymesh/local-store";
import type { LocalTaskStore } from "@envoymesh/local-store";
import type {
  EnvoyEnvelope,
  UnsignedEnvoyEnvelope,
} from "@envoymesh/protocol";
import type { EnvoyMesh } from "@envoymesh/network";
import { isPrivateLanTcpDialHint } from "@envoymesh/network";
import type { ChatDeliverResult } from "./chat-outbound-deliver.js";
import { deliverCallEnvelopeWithRetry } from "./chat-outbound-deliver.js";
import type { CallManager } from "./call-manager.js";
import type { PersistedNodeConfig } from "./node-config-store.js";
import { webrtcCallTrace, webrtcCallWarn, shortCallId } from "./webrtc-call-trace.js";
import { pickConnectedTransportForOwner, pickLibp2pFromConnectedPeers, resolveRecipientEnvelopePeerId } from "./peer-transport-resolve.js";
import { mergeDialablePeerListenAddrs } from "./outbound-dial-hints.js";

// --------------------------------------------------------------------------
// Constants
// --------------------------------------------------------------------------

/**
 * Phase 42 — default `iceServers` injected into `call.invite` when the
 * caller did not provide a list and the home's `node-config.json` has none.
 * Three public STUN endpoints; TURN is user-configured (Phase 42H).
 */
const DEFAULT_ICE_SERVERS: { urls: string; username?: string; credential?: string }[] = [
  { urls: "stun:stun.l.google.com:19302" },
  { urls: "stun:stun.cloudflare.com:3478" },
  { urls: "stun:global.stun.twilio.com:3478" },
];

// --------------------------------------------------------------------------
// Deps interface
// --------------------------------------------------------------------------

export interface NodeCallSignalingDeps {
  /** Current node profile (may be undefined before init). */
  getProfile(): NodeProfile | undefined;

  /** The running mesh — throws if not started. */
  requireMesh(): EnvoyMesh;

  /** The running mesh — returns undefined if not started. */
  reachableMesh(): EnvoyMesh | undefined;

  /** Per-node call session manager. */
  callManager: CallManager;

  /** Resolve a trust record for an owner id. */
  getTrustRecord(ownerId: string): Promise<{ displayName?: string } | undefined>;

  /** List all peer directory records. */
  listPeerRecords(): Promise<
    Array<{
      ownerId: string;
      peerId: string;
      listenAddrs?: string[];
      lastSeenAt: string;
    }>
  >;

  /** Look up a peer by owner id. */
  getPeerByOwnerId(ownerId: string): Promise<
    | { peerId: string; listenAddrs?: string[]; ownerId?: string; lastSeenAt?: string }
    | undefined
  >;

  /** Append an audit event (best-effort). */
  appendAuditEvent(event: ReturnType<typeof createAuditEvent>): Promise<void>;

  /** Load persisted node config. */
  loadConfig(): Promise<PersistedNodeConfig | undefined>;

  /** In-memory owner → libp2p transport cache. */
  lastLibp2pTransportByOwner: Map<string, { peerId: string; listenAddrs?: string[] }>;

  /** Build dial hints for a chat peer. */
  dialHintsForChat(
    recipientPeerId: string,
    peerListenAddrs: string[] | undefined,
  ): Promise<string[]>;

  /** Resolve transport info for an owner. */
  resolvePeerTransportForOwner(targetOwnerId: string): Promise<{
    transportPeerId: string;
    recipientEnvelopePeerId: string | undefined;
    listenAddrs: string[] | undefined;
  }>;

  /** Serialise outbound sends to the same transport peer. */
  withChatSendLock<T>(transportPeerId: string, fn: () => Promise<T>): Promise<T>;

  /** Warm a contact's connection before sending. */
  warmContactConnection(
    peerOwnerId: string,
    options?: WarmContactConnectionOptions,
  ): Promise<void>;

  /** Race a promise against a timeout. */
  raceWithTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T>;
}

// --------------------------------------------------------------------------
// Internal helpers (not exported)
// --------------------------------------------------------------------------

async function _effectiveCallIceServers(
  deps: NodeCallSignalingDeps,
  callerSupplied?: { urls: string; username?: string; credential?: string }[],
): Promise<{ urls: string; username?: string; credential?: string }[]> {
  if (callerSupplied !== undefined) return callerSupplied;
  const config = await deps.loadConfig();
  if (config?.iceServers && config.iceServers.length > 0) return config.iceServers;
  return DEFAULT_ICE_SERVERS;
}

function _recordCallRejected(deps: NodeCallSignalingDeps, callId: string, _reason: string): void {
  try {
    deps.callManager.rejectCall(
      callId,
      "error" as "busy" | "declined" | "offline" | "error" | "no_answer",
    );
  } catch {
    // best-effort
  }
}

// --------------------------------------------------------------------------
// deliverCallEnvelopeToTransportPeer
// --------------------------------------------------------------------------

export async function deliverCallEnvelopeToTransportPeer(
  deps: NodeCallSignalingDeps,
  transportPeerId: string,
  envelope: EnvoyEnvelope,
): Promise<void> {
  const mesh = deps.requireMesh();
  const conn = mesh.getPeerConnectionInfo(transportPeerId);
  if (conn.connected || mesh.getConnectedPeerIds().includes(transportPeerId)) {
    await mesh.sendChat(transportPeerId, envelope, { dialHints: [] });
    return;
  }
  await _deliverCallEnvelope(deps, transportPeerId, envelope, [], undefined, false);
}

// --------------------------------------------------------------------------
// _deliverCallEnvelope
// --------------------------------------------------------------------------

async function _deliverCallEnvelope(
  deps: NodeCallSignalingDeps,
  transportPeerId: string,
  envelope: EnvoyEnvelope,
  dialHints: string[],
  listenAddrs?: string[],
  preferCircuitHints?: boolean,
): Promise<ChatDeliverResult> {
  return deps.withChatSendLock(transportPeerId, async () => {
    const mesh = deps.requireMesh();
    let conn = mesh.getPeerConnectionInfo(transportPeerId);
    webrtcCallTrace("node:deliver-call-envelope", {
      intent: envelope.intent,
      callId: shortCallId(
        typeof envelope.payload === "object" &&
          envelope.payload !== null &&
          "callId" in envelope.payload
          ? String((envelope.payload as { callId?: string }).callId)
          : undefined,
      ),
      peer: shortCallId(transportPeerId),
      connected: conn.connected,
      direct: conn.direct,
      hintCount: dialHints.length,
    });
    if (!conn.connected) {
      const dialTargets = [...new Set([...(listenAddrs ?? []), ...dialHints])]
        .map((a) => a.trim())
        .filter(Boolean);
      if (dialTargets.length > 0) {
        const ordered = [...dialTargets].sort((a, b) => {
          const aLan = isPrivateLanTcpDialHint(a) ? 1 : 0;
          const bLan = isPrivateLanTcpDialHint(b) ? 1 : 0;
          if (aLan !== bLan) return bLan - aLan;
          const aCircuit = a.includes("/p2p-circuit/") ? 1 : 0;
          const bCircuit = b.includes("/p2p-circuit/") ? 1 : 0;
          if (aCircuit !== bCircuit) return aCircuit - bCircuit;
          return 0;
        });
        for (const addr of ordered) {
          try {
            await mesh.dial(addr);
            conn = mesh.getPeerConnectionInfo(transportPeerId);
            if (conn.connected) break;
          } catch {
            /* try next addr */
          }
        }
      }
    }
    const preferCircuits = preferCircuitHints ?? !conn.direct;
    const wasConnected = conn.connected;
    if (conn.connected) {
      try {
        await mesh.sendChat(transportPeerId, envelope, {
          dialHints: [],
          preferCircuitHints: preferCircuits && !conn.direct,
        });
        webrtcCallTrace("node:deliver-call-fast-path-ok", {
          peer: shortCallId(transportPeerId),
          direct: conn.direct,
        });
        return { delivered: true, deliveredAt: new Date().toISOString() };
      } catch (fastErr) {
        webrtcCallWarn("node:deliver-call-fast-path-failed", {
          peer: shortCallId(transportPeerId),
          error: fastErr instanceof Error ? fastErr.message.slice(0, 120) : String(fastErr),
        });
        console.warn(
          `[call] connected send failed for ${transportPeerId.slice(0, 12)}…, retrying:`,
          fastErr instanceof Error ? fastErr.message : fastErr,
        );
      }
    }
    return deliverCallEnvelopeWithRetry({
      mesh,
      transportPeerId,
      envelope,
      dialHints: wasConnected ? [] : dialHints,
      peerListenAddrs: wasConnected ? [] : listenAddrs,
      preferCircuitHints: preferCircuits,
      rebuildDialHints: wasConnected
        ? undefined
        : () => deps.dialHintsForChat(transportPeerId, listenAddrs),
    });
  });
}

// --------------------------------------------------------------------------
// _sendCallResponseEnvelope
// --------------------------------------------------------------------------

async function _sendCallResponseEnvelope(
  deps: NodeCallSignalingDeps,
  peerOwnerId: string,
  unsigned: UnsignedEnvoyEnvelope,
  _intent: string,
): Promise<boolean> {
  const profile = deps.getProfile();
  if (!profile) return false;
  try {
    const callId =
      typeof unsigned.payload === "object" &&
      unsigned.payload !== null &&
      "callId" in unsigned.payload
        ? String((unsigned.payload as { callId?: string }).callId)
        : undefined;
    const cachedPeerId = callId ? deps.callManager.getSessionRemoteTransportPeerId(callId) : null;
    if (cachedPeerId) {
      const mesh = deps.requireMesh();
      const conn = mesh.getPeerConnectionInfo(cachedPeerId);
      if (conn.connected || mesh.getConnectedPeerIds().includes(cachedPeerId)) {
        try {
          const transport = await deps.resolvePeerTransportForOwner(peerOwnerId);
          unsigned.recipientPeerId = transport.recipientEnvelopePeerId;
          const { signUnsignedEnvelope } = await import("@envoymesh/identity");
          const envelope = signUnsignedEnvelope(unsigned, profile.device.privateKeyPem);
          await deliverCallEnvelopeToTransportPeer(deps, cachedPeerId, envelope as EnvoyEnvelope);
          webrtcCallTrace("call-response:fast", {
            intent: _intent,
            peer: shortCallId(cachedPeerId),
          });
          return true;
        } catch {
          webrtcCallTrace("call-response:fast-failed-fallback", { intent: _intent });
        }
      }
    }

    const transport = await deps.resolvePeerTransportForOwner(peerOwnerId);
    const mesh = deps.requireMesh();
    const records = await deps.listPeerRecords();
    const connectedPeerIds = mesh.getConnectedPeerIds();
    const liveConnected = pickConnectedTransportForOwner(
      records,
      peerOwnerId,
      connectedPeerIds,
      deps.lastLibp2pTransportByOwner,
    );
    let targetPeerId = liveConnected?.peerId ?? transport.transportPeerId;
    let listenAddrs = liveConnected?.listenAddrs ?? transport.listenAddrs;
    let conn = mesh.getPeerConnectionInfo(targetPeerId);
    if (!conn.connected) {
      targetPeerId = transport.transportPeerId;
      listenAddrs = transport.listenAddrs;
      conn = mesh.getPeerConnectionInfo(targetPeerId);
    }
    if (!conn.connected) {
      try {
        await mesh.dial(targetPeerId);
        conn = mesh.getPeerConnectionInfo(targetPeerId);
      } catch {
        /* try listen addrs */
      }
    }
    if (!conn.connected) {
      const addrs = (listenAddrs ?? []).map((a) => a.trim()).filter(Boolean);
      if (addrs.length > 0) {
        const ordered = [...addrs].sort((a, b) => {
          const aLan = isPrivateLanTcpDialHint(a) ? 1 : 0;
          const bLan = isPrivateLanTcpDialHint(b) ? 1 : 0;
          if (aLan !== bLan) return bLan - aLan;
          const aCircuit = a.includes("/p2p-circuit/") ? 1 : 0;
          const bCircuit = b.includes("/p2p-circuit/") ? 1 : 0;
          if (aCircuit !== bCircuit) return aCircuit - bCircuit;
          return 0;
        });
        for (const addr of ordered) {
          try {
            await mesh.dial(addr);
            conn = mesh.getPeerConnectionInfo(transport.transportPeerId);
            targetPeerId = transport.transportPeerId;
            if (conn.connected) break;
          } catch {
            /* try next addr */
          }
        }
      }
    }
    const preferCircuitHints = !conn.direct;
    let dialHints: string[];
    try {
      dialHints = await deps.raceWithTimeout(
        deps.dialHintsForChat(targetPeerId, listenAddrs),
        10_000,
        "_dialHintsForChat",
      );
    } catch (hintErr) {
      console.warn(
        `[call-response] dial hints failed for ${peerOwnerId}, using listen addrs:`,
        hintErr instanceof Error ? hintErr.message : hintErr,
      );
      dialHints = mergeDialablePeerListenAddrs(targetPeerId, listenAddrs ?? []);
    }
    unsigned.recipientPeerId = transport.recipientEnvelopePeerId;
    const { signUnsignedEnvelope } = await import("@envoymesh/identity");
    const envelope = signUnsignedEnvelope(unsigned, profile.device.privateKeyPem);
    const deliverResult = await _deliverCallEnvelope(
      deps,
      targetPeerId,
      envelope,
      conn.connected ? [] : dialHints,
      conn.connected ? [] : listenAddrs,
      preferCircuitHints,
    );
    if (!deliverResult.delivered) {
      webrtcCallWarn("call-response:not-delivered", {
        intent: _intent,
        peer: shortCallId(targetPeerId),
        callId: shortCallId(
          typeof unsigned.payload === "object" &&
            unsigned.payload !== null &&
            "callId" in unsigned.payload
            ? String((unsigned.payload as { callId?: string }).callId)
            : undefined,
        ),
      });
      console.warn(
        `[call-response] could not deliver ${_intent} to ${peerOwnerId.slice(0, 24)}…`,
      );
      return false;
    }
    webrtcCallTrace("call-response:delivered", {
      intent: _intent,
      peer: shortCallId(targetPeerId),
    });
    return true;
  } catch (err) {
    console.warn(
      `[call-response] could not deliver ${_intent} to ${peerOwnerId}:`,
      err instanceof Error ? err.message : err,
    );
    return false;
  }
}

