// --------------------------------------------------------------------------
// sendCallInvite
// --------------------------------------------------------------------------

export async function sendCallInvite(
  deps: NodeCallSignalingDeps,
  targetOwnerId: string,
  sdpOffer: string,
  iceServers?: { urls: string; username?: string; credential?: string }[],
  callType: CallMediaType = "audio",
): Promise<string | null> {
  console.log(`[sendCallInvite] invoked target=${targetOwnerId.slice(0, 24)} sdpLen=${sdpOffer.length}`);
  const profile = deps.getProfile();
  if (!profile) return null;
  if (!deps.reachableMesh()) return null;

  const callId = randomUUID();
  const { derivePeerId } = await import("@envoymesh/identity");
  const senderPeerId = derivePeerId(profile.device.publicKeyPem);
  webrtcCallTrace("sendCallInvite:start", {
    callId: shortCallId(callId),
    target: shortCallId(targetOwnerId),
    sdpLen: sdpOffer.length,
    path2: Boolean(iceServers?.length),
  });
  const trust = await deps.getTrustRecord(targetOwnerId);
  const peerDisplayName = trust?.displayName?.trim() || targetOwnerId;

  const initiated = deps.callManager.outboundCallInitiated(
    callId,
    profile.owner.ownerId,
    targetOwnerId,
    peerDisplayName,
    callType,
  );
  if (!initiated) return null;

  let transport;
  try {
    transport = await deps.resolvePeerTransportForOwner(targetOwnerId);
  } catch (err) {
    webrtcCallWarn("sendCallInvite:transport-resolve-failed", {
      callId: shortCallId(callId),
      target: shortCallId(targetOwnerId),
      error: err instanceof Error ? err.message.slice(0, 120) : String(err),
    });
    console.warn(`[sendCallInvite] peer transport resolve failed for ${targetOwnerId}:`, err);
    _recordCallRejected(deps, callId, "peer_unreachable");
    return null;
  }
  const { transportPeerId, recipientEnvelopePeerId, listenAddrs } = transport;

  const mesh = deps.requireMesh();
  const records = await deps.listPeerRecords();
  const connectedPeerIds = mesh.getConnectedPeerIds();
  const liveConnected = pickConnectedTransportForOwner(
    records,
    targetOwnerId,
    connectedPeerIds,
    deps.lastLibp2pTransportByOwner,
  );
  const targetPeerId = liveConnected?.peerId ?? transportPeerId;
  const connBeforeWarm = mesh.getPeerConnectionInfo(targetPeerId);
  webrtcCallTrace("sendCallInvite:transport-ready", {
    callId: shortCallId(callId),
    target: shortCallId(targetOwnerId),
    transport: shortCallId(targetPeerId),
    connected: connBeforeWarm.connected,
    direct: connBeforeWarm.direct,
  });
  console.log(
    `[sendCallInvite] target=${targetOwnerId.slice(0, 24)} transport=${targetPeerId.slice(0, 12)} connected=${connBeforeWarm.connected} direct=${connBeforeWarm.direct}`,
  );
  if (!connBeforeWarm.connected && !liveConnected) {
    try {
      await deps.warmContactConnection(targetOwnerId, {
        ...(!connBeforeWarm.direct ? { upgradeRelayToDirect: true } : undefined),
      });
    } catch (warmErr) {
      console.warn(
        `[sendCallInvite] warm before invite failed for ${targetOwnerId}:`,
        warmErr instanceof Error ? warmErr.message : warmErr,
      );
    }
  }

  const connAfterWarm = mesh.getPeerConnectionInfo(targetPeerId);

  const effectiveIceServers = await _effectiveCallIceServers(deps, iceServers);

  let dialHints: string[];
  if (connAfterWarm.connected || liveConnected) {
    dialHints = [];
  } else {
    try {
      dialHints = await deps.raceWithTimeout(
        deps.dialHintsForChat(targetPeerId, listenAddrs),
        10_000,
        "_dialHintsForChat",
      );
    } catch (hintErr) {
      console.warn(
        `[sendCallInvite] dial hints failed for ${targetOwnerId}, using listen addrs:`,
        hintErr instanceof Error ? hintErr.message : hintErr,
      );
      dialHints = mergeDialablePeerListenAddrs(transportPeerId, listenAddrs ?? []);
    }
  }

  const preferCircuitHints = connAfterWarm.connected ? !connAfterWarm.direct : !connAfterWarm.direct;

  const { createCallInvitePayload, createUnsignedEnvelope } = await import("@envoymesh/protocol");
  const { signUnsignedEnvelope } = await import("@envoymesh/identity");

  const invitePayload = createCallInvitePayload({
    callId,
    callerOwnerId: profile.owner.ownerId,
    callerPeerId: senderPeerId,
    callType,
    sdpOffer,
    iceServers: effectiveIceServers,
  });

  const unsigned = createUnsignedEnvelope({
    intent: "call.invite",
    senderPeerId,
    senderPublicKey: profile.device.publicKeyPem,
    recipientPeerId: recipientEnvelopePeerId,
    senderRole: "human",
    recipientRole: "human",
    payload: invitePayload,
  });
  const envelope = signUnsignedEnvelope(unsigned, profile.device.privateKeyPem) as any;

  deps.callManager.setOutboundTransportPeerId(callId, targetPeerId);

  let deliverResult: ChatDeliverResult;
  try {
    if (connAfterWarm.connected || mesh.getConnectedPeerIds().includes(targetPeerId)) {
      await mesh.sendChat(targetPeerId, envelope, { dialHints: [] });
      deliverResult = { delivered: true, deliveredAt: new Date().toISOString() };
    } else {
      deliverResult = await _deliverCallEnvelope(
        deps,
        targetPeerId,
        envelope,
        dialHints,
        listenAddrs,
        preferCircuitHints,
      );
    }
  } catch (deliverErr) {
    const detail = deliverErr instanceof Error ? deliverErr.message : String(deliverErr);
    webrtcCallWarn("sendCallInvite:delivery-failed", {
      callId: shortCallId(callId),
      target: shortCallId(targetOwnerId),
      error: detail.slice(0, 120),
    });
    console.warn(`[sendCallInvite] call.invite delivery failed callId=${callId}:`, detail);
    deps.callManager.reportOutboundDeliveryFailed(
      callId,
      "Could not reach contact — check relay connection and try again.",
    );
    await deps.appendAuditEvent(
      createAuditEvent({
        type: "message.rejected",
        intent: "call.invite",
        outcome: "deny",
        summary: `call.invite delivery failed callId=${callId}: ${detail}`,
        remotePeerId: targetOwnerId,
      }),
    ).catch(() => undefined);
    return null;
  }

  if (!deliverResult.delivered) {
    const detail = "No reachable path to contact before call.invite send";
    webrtcCallWarn("sendCallInvite:delivery-not-delivered", {
      callId: shortCallId(callId),
      target: shortCallId(targetOwnerId),
    });
    console.warn(`[sendCallInvite] call.invite delivery failed callId=${callId}:`, detail);
    deps.callManager.reportOutboundDeliveryFailed(
      callId,
      "Could not reach contact — check relay connection and try again.",
    );
    await deps.appendAuditEvent(
      createAuditEvent({
        type: "message.rejected",
        intent: "call.invite",
        outcome: "deny",
        summary: `call.invite delivery failed callId=${callId}: ${detail}`,
        remotePeerId: targetOwnerId,
      }),
    ).catch(() => undefined);
    return null;
  }

  await deps.appendAuditEvent(
    createAuditEvent({
      type: "message.sent",
      intent: "call.invite",
      outcome: "allow",
      summary: `call.invite sent to ${targetOwnerId} callId=${callId}`,
      remotePeerId: targetOwnerId,
    }),
  ).catch(() => undefined);

  console.log(`[sendCallInvite] call.invite delivered to ${targetOwnerId} callId=${callId}`);
  webrtcCallTrace("sendCallInvite:delivered", {
    callId: shortCallId(callId),
    target: shortCallId(targetOwnerId),
  });

  return callId;
}

// --------------------------------------------------------------------------
// sendCallReinvite
// --------------------------------------------------------------------------

export async function sendCallReinvite(
  deps: NodeCallSignalingDeps,
  callId: string,
  sdpOffer: string,
  iceServers?: { urls: string; username?: string; credential?: string }[],
  reason: "path1_timeout" | "path1_failed" = "path1_timeout",
): Promise<boolean> {
  const profile = deps.getProfile();
  if (!profile || !deps.reachableMesh()) return false;

  const callerOwnerId = profile.owner.ownerId;
  if (!deps.callManager.canSendOutboundReinvite(callId, callerOwnerId)) return false;

  const peerOwnerId = deps.callManager.getSessionPeerOwnerId(callId);
  if (!peerOwnerId) return false;

  const effectiveIceServers = await _effectiveCallIceServers(deps, iceServers);
  if (effectiveIceServers.length === 0) return false;

  let transport;
  try {
    transport = await deps.resolvePeerTransportForOwner(peerOwnerId);
  } catch (err) {
    console.warn(`[sendCallReinvite] peer transport resolve failed for ${peerOwnerId}:`, err);
    return false;
  }
  const { transportPeerId, recipientEnvelopePeerId, listenAddrs } = transport;

  const mesh = deps.requireMesh();
  let conn = mesh.getPeerConnectionInfo(transportPeerId);
  if (!conn.connected) {
    for (const addr of listenAddrs ?? []) {
      const trimmed = addr.trim();
      if (!trimmed) continue;
      try {
        await mesh.dial(trimmed);
        conn = mesh.getPeerConnectionInfo(transportPeerId);
        if (conn.connected) break;
      } catch {
        /* try next addr */
      }
    }
  }
  const preferCircuitHints = !conn.direct;

  const dialHints = await deps.raceWithTimeout(
    deps.dialHintsForChat(transportPeerId, listenAddrs),
    30_000,
    "_dialHintsForChat",
  );

  const { derivePeerId } = await import("@envoymesh/identity");
  const senderPeerId = derivePeerId(profile.device.publicKeyPem);
  const { createCallReinvitePayload, createUnsignedEnvelope } = await import("@envoymesh/protocol");
  const { signUnsignedEnvelope } = await import("@envoymesh/identity");

  const reinvitePayload = createCallReinvitePayload({
    callId,
    callerOwnerId,
    callerPeerId: senderPeerId,
    sdpOffer,
    iceServers: effectiveIceServers,
    reason,
    transportPath: "path2",
  });

  const unsigned = createUnsignedEnvelope({
    intent: "call.reinvite",
    senderPeerId,
    senderPublicKey: profile.device.publicKeyPem,
    recipientPeerId: recipientEnvelopePeerId,
    senderRole: "human",
    recipientRole: "human",
    payload: reinvitePayload,
  });
  const envelope = signUnsignedEnvelope(unsigned, profile.device.privateKeyPem) as any;

  const records = await deps.listPeerRecords();
  const liveConnected = pickLibp2pFromConnectedPeers(
    records,
    peerOwnerId,
    mesh.getConnectedPeerIds(),
  );
  const targetPeerId = liveConnected?.peerId ?? transportPeerId;
  conn = mesh.getPeerConnectionInfo(targetPeerId);

  let deliverResult: ChatDeliverResult;
  try {
    if (conn.connected || mesh.getConnectedPeerIds().includes(targetPeerId)) {
      await mesh.sendChat(targetPeerId, envelope, { dialHints: [] });
      deliverResult = { delivered: true, deliveredAt: new Date().toISOString() };
    } else {
      deliverResult = await _deliverCallEnvelope(
        deps,
        targetPeerId,
        envelope,
        dialHints,
        listenAddrs,
        preferCircuitHints,
      );
    }
  } catch (deliverErr) {
    console.warn(
      `[sendCallReinvite] call.reinvite delivery failed callId=${callId}:`,
      deliverErr instanceof Error ? deliverErr.message : deliverErr,
    );
    return false;
  }

  await deps.appendAuditEvent(
    createAuditEvent({
      type: deliverResult.delivered ? "message.sent" : "message.rejected",
      intent: "call.reinvite",
      outcome: deliverResult.delivered ? "allow" : "deny",
      summary: deliverResult.delivered
        ? `call.reinvite sent callId=${callId} reason=${reason}`
        : `call.reinvite delivery failed callId=${callId}`,
      remotePeerId: peerOwnerId,
    }),
  ).catch(() => undefined);

  return deliverResult.delivered;
}

// --------------------------------------------------------------------------
// acceptCallInvite
// --------------------------------------------------------------------------

export async function acceptCallInvite(
  deps: NodeCallSignalingDeps,
  callId: string,
  sdpAnswer: string,
  iceServers?: { urls: string; username?: string; credential?: string }[],
): Promise<boolean> {
  const profile = deps.getProfile();
  if (!profile) return false;

  const calleeOwnerId = profile.owner.ownerId;
  const { derivePeerId } = await import("@envoymesh/identity");
  const calleePeerId = derivePeerId(profile.device.publicKeyPem);

  const peerOwnerId = deps.callManager.getSessionPeerOwnerId(callId);
  if (!peerOwnerId) return false;

  const sessionStatus = deps.callManager.getSessionStatus(callId);
  if (sessionStatus !== "ringing" && sessionStatus !== "active") return false;

  const { createCallAcceptPayload, createUnsignedEnvelope } = await import("@envoymesh/protocol");

  const payload = createCallAcceptPayload({
    callId,
    calleeOwnerId,
    calleePeerId,
    sdpAnswer,
    iceServers,
  });

  const unsigned = createUnsignedEnvelope({
    intent: "call.accept",
    senderPeerId: calleePeerId,
    senderPublicKey: profile.device.publicKeyPem,
    recipientRole: "human",
    payload,
  });
  const delivered = await _sendCallResponseEnvelope(deps, peerOwnerId, unsigned, "call.accept");
  if (!delivered) return false;

  if (sessionStatus === "ringing") {
    const accepted = deps.callManager.acceptInboundCall(callId, calleeOwnerId);
    if (!accepted) return false;
  }
  return true;
}

// --------------------------------------------------------------------------
// declineCallInvite
// --------------------------------------------------------------------------

export async function declineCallInvite(
  deps: NodeCallSignalingDeps,
  callId: string,
  reason: string,
): Promise<boolean> {
  const profile = deps.getProfile();
  if (!profile) return false;

  const rejected = deps.callManager.rejectCall(
    callId,
    reason as "busy" | "declined" | "offline" | "error" | "no_answer",
  );
  if (!rejected) return false;

  const peerOwnerId = deps.callManager.getSessionPeerOwnerId(callId);
  if (!peerOwnerId) return false;

  const { createCallRejectPayload, createUnsignedEnvelope } = await import("@envoymesh/protocol");

  const calleeOwnerId = profile.owner.ownerId;
  const { derivePeerId } = await import("@envoymesh/identity");
  const calleePeerId = derivePeerId(profile.device.publicKeyPem);
  const payload = createCallRejectPayload({
    callId,
    calleeOwnerId,
    calleePeerId,
    reason: reason as "busy" | "declined" | "no_answer" | "offline" | "error",
  });

  const unsigned = createUnsignedEnvelope({
    intent: "call.reject",
    senderPeerId: calleePeerId,
    senderPublicKey: profile.device.publicKeyPem,
    recipientRole: "human",
    payload,
  });
  await _sendCallResponseEnvelope(deps, peerOwnerId, unsigned, "call.reject");
  return true;
}

// --------------------------------------------------------------------------
// endCall
// --------------------------------------------------------------------------

export async function endCall(
  deps: NodeCallSignalingDeps,
  callId: string,
): Promise<boolean> {
  const profile = deps.getProfile();
  if (!profile) return false;

  const ended = deps.callManager.hangupCall(callId, "normal");
  if (!ended) return false;

  const peerOwnerId = deps.callManager.getSessionPeerOwnerId(callId);
  if (!peerOwnerId) {
    return true;
  }

  const { createCallHangupPayload, createUnsignedEnvelope } = await import("@envoymesh/protocol");

  const { derivePeerId } = await import("@envoymesh/identity");
  const senderPeerId = derivePeerId(profile.device.publicKeyPem);
  const payload = createCallHangupPayload({ callId, reason: "normal" });

  const unsigned = createUnsignedEnvelope({
    intent: "call.hangup",
    senderPeerId,
    senderPublicKey: profile.device.publicKeyPem,
    recipientRole: "human",
    payload,
  });
  await _sendCallResponseEnvelope(deps, peerOwnerId, unsigned, "call.hangup");
  return true;
}

// --------------------------------------------------------------------------
// setCallMuted
// --------------------------------------------------------------------------

export async function setCallMuted(
  deps: NodeCallSignalingDeps,
  callId: string,
  muted: boolean,
): Promise<boolean> {
  const profile = deps.getProfile();
  if (!profile) return false;

  const updated = deps.callManager.setMute(callId, muted);
  if (!updated) return false;

  const peerOwnerId = deps.callManager.getSessionPeerOwnerId(callId);
  if (!peerOwnerId) return false;

  const { createCallMutePayload, createUnsignedEnvelope } = await import("@envoymesh/protocol");

  const { derivePeerId } = await import("@envoymesh/identity");
  const senderPeerId = derivePeerId(profile.device.publicKeyPem);
  const payload = createCallMutePayload({ callId, muted });

  const unsigned = createUnsignedEnvelope({
    intent: "call.mute",
    senderPeerId,
    senderPublicKey: profile.device.publicKeyPem,
    recipientRole: "human",
    payload,
  });
  await _sendCallResponseEnvelope(deps, peerOwnerId, unsigned, "call.mute");
  return true;
}

// --------------------------------------------------------------------------
// sendIceCandidate
// --------------------------------------------------------------------------

export async function sendIceCandidate(
  deps: NodeCallSignalingDeps,
  callId: string,
  candidate: {
    candidate: string;
    sdpMid: string | null;
    sdpMLineIndex: number | null;
    usernameFragment?: string | null;
  },
): Promise<boolean> {
  const profile = deps.getProfile();
  if (!profile) return false;
  const status = deps.callManager.getSessionStatus(callId);
  if (status !== "ringing" && status !== "active") return false;

  const peerOwnerId = deps.callManager.getSessionPeerOwnerId(callId);
  if (!peerOwnerId) return false;

  const { createCallIceCandidatePayload, createUnsignedEnvelope } = await import("@envoymesh/protocol");
  const { derivePeerId } = await import("@envoymesh/identity");
  const senderPeerId = derivePeerId(profile.device.publicKeyPem);
  const payload = createCallIceCandidatePayload({ callId, candidate });
  const unsigned = createUnsignedEnvelope({
    intent: "call.ice-candidate",
    senderPeerId,
    senderPublicKey: profile.device.publicKeyPem,
    recipientRole: "human",
    payload,
  });
  await _sendCallResponseEnvelope(deps, peerOwnerId, unsigned, "call.ice-candidate");
  return true;
}

// --------------------------------------------------------------------------
// sendCallRejectToOwner
// --------------------------------------------------------------------------

export async function sendCallRejectToOwner(
  deps: NodeCallSignalingDeps,
  callId: string,
  callerOwnerId: string,
  reason: import("@envoymesh/protocol").CallRejectPayload["reason"],
): Promise<void> {
  const profile = deps.getProfile();
  if (!profile) return;

  const { createCallRejectPayload, createUnsignedEnvelope } = await import("@envoymesh/protocol");
  const calleeOwnerId = profile.owner.ownerId;
  const { derivePeerId } = await import("@envoymesh/identity");
  const calleePeerId = derivePeerId(profile.device.publicKeyPem);
  const payload = createCallRejectPayload({
    callId,
    calleeOwnerId,
    calleePeerId,
    reason,
  });
  const unsigned = createUnsignedEnvelope({
    intent: "call.reject",
    senderPeerId: calleePeerId,
    senderPublicKey: profile.device.publicKeyPem,
    recipientRole: "human",
    payload,
  });
  await _sendCallResponseEnvelope(deps, callerOwnerId, unsigned, "call.reject");
}

// --------------------------------------------------------------------------
// wireCallManagerRemoteSignals
// --------------------------------------------------------------------------

export function wireCallManagerRemoteSignals(deps: NodeCallSignalingDeps): void {
  deps.callManager.setRemoteSignalHandler((req) => {
    void sendCallRejectToOwner(deps, req.callId, req.peerOwnerId, req.reason);
  });
}

