+// --------------------------------------------------------------------------
+// acceptCallInvite
+// --------------------------------------------------------------------------
+
+export async function acceptCallInvite(
+  deps: NodeCallSignalingDeps,
+  callId: string,
+  sdpAnswer: string,
+  iceServers?: { urls: string; username?: string; credential?: string }[],
+): Promise<boolean> {
+  const profile = deps.getProfile();
+  if (!profile) return false;
+
+  const calleeOwnerId = profile.owner.ownerId;
+  const { derivePeerId } = await import("@envoymesh/identity");
+  const calleePeerId = derivePeerId(profile.device.publicKeyPem);
+
+  const peerOwnerId = deps.callManager.getSessionPeerOwnerId(callId);
+  if (!peerOwnerId) return false;
+
+  const sessionStatus = deps.callManager.getSessionStatus(callId);
+  if (sessionStatus !== "ringing" && sessionStatus !== "active") return false;
+
+  const { createCallAcceptPayload, createUnsignedEnvelope } = await import("@envoymesh/protocol");
+
+  const payload = createCallAcceptPayload({
+    callId,
+    calleeOwnerId,
+    calleePeerId,
+    sdpAnswer,
+    iceServers,
+  });
+
+  const unsigned = createUnsignedEnvelope({
+    intent: "call.accept",
+    senderPeerId: calleePeerId,
+    senderPublicKey: profile.device.publicKeyPem,
+    recipientRole: "human",
+    payload,
+  });
+  const delivered = await _sendCallResponseEnvelope(deps, peerOwnerId, unsigned, "call.accept");
+  if (!delivered) return false;
+
+  if (sessionStatus === "ringing") {
+    const accepted = deps.callManager.acceptInboundCall(callId, calleeOwnerId);
+    if (!accepted) return false;
+  }
+  return true;
+}
