+// --------------------------------------------------------------------------
+// declineCallInvite
+// --------------------------------------------------------------------------
+
+export async function declineCallInvite(
+  deps: NodeCallSignalingDeps,
+  callId: string,
+  reason: string,
+): Promise<boolean> {
+  const profile = deps.getProfile();
+  if (!profile) return false;
+
+  const rejected = deps.callManager.rejectCall(
+    callId,
+    reason as "busy" | "declined" | "offline" | "error" | "no_answer",
+  );
+  if (!rejected) return false;
+
+  const peerOwnerId = deps.callManager.getSessionPeerOwnerId(callId);
+  if (!peerOwnerId) return false;
+
+  const { createCallRejectPayload, createUnsignedEnvelope } = await import("@envoymesh/protocol");
+
+  const calleeOwnerId = profile.owner.ownerId;
+  const { derivePeerId } = await import("@envoymesh/identity");
+  const calleePeerId = derivePeerId(profile.device.publicKeyPem);
+  const payload = createCallRejectPayload({
+    callId,
+    calleeOwnerId,
+    calleePeerId,
+    reason: reason as "busy" | "declined" | "no_answer" | "offline" | "error",
+  });
+
+  const unsigned = createUnsignedEnvelope({
+    intent: "call.reject",
+    senderPeerId: calleePeerId,
+    senderPublicKey: profile.device.publicKeyPem,
+    recipientRole: "human",
+    payload,
+  });
+  await _sendCallResponseEnvelope(deps, peerOwnerId, unsigned, "call.reject");
+  return true;
+}
